function updateCart(){el('basketCount').textContent=[...cart.values()].reduce((n,x)=>n+x.qty,0);const lines=[...cart.values()];el('cartLines').innerHTML=lines.length?lines.map(x=>`<div class="list-row"><div><strong>${esc(x.product.name)}</strong><small>${money(x.product.price_pkr)} each</small></div><div style="display:flex;align-items:center;gap:7px"><button class="btn small qty" data-id="${x.product.id}" data-delta="-1">−</button><b>${x.qty}</b><button class="btn small qty" data-id="${x.product.id}" data-delta="1">+</button><button class="btn small" data-remove="${x.product.id}">Remove</button></div></div>`).join(''):'<div class="empty" style="padding:18px"><h3>Your basket is empty</h3><p>Add a real product from the marketplace.</p></div>';const total=lines.reduce((s,x)=>s+Number(x.product.price_pkr)*x.qty,0);const discount=lines.reduce((n,x)=>{const gross=Number(x.product.price_pkr)*x.qty;const pool=Math.round((gross*Number(x.product.vendors?.commission_rate||0)+Number.EPSILON)*100)/100;const company=Math.round((gross*0.05+Number.EPSILON)*100)/100;return n+Math.min(Math.round((gross*Number(x.product.vendors?.sale_distribution?.buyer_discount||0)/100+Number.EPSILON)*100)/100,Math.max(0,pool-company))},0);const retailSaving=lines.reduce((n,x)=>n+Math.max(Number(x.product.compare_at_price_pkr||0)-Number(x.product.price_pkr),0)*x.qty,0);el('cartRetailSaving').textContent=retailSaving?'Product sale savings: '+money(retailSaving)+' · Already included in the prices shown.':'';el('cartSubtotal').textContent=money(total);el('cartDiscount').textContent='Buyer discount: '+money(discount)+' · Products after discount: '+money(total-discount);el('deliverySummary').textContent=deliveryFee===null?'Delivery charges are awaiting company configuration.':'Shipping: '+money(deliveryFee)+' · Order total: '+money(total-discount+deliveryFee)+'. '+deliveryPolicy;el('checkoutForm').classList.toggle('hidden',!lines.length)}
