async function boot(){renderPackages();const {data}=await db.auth.getSession();session=data.session;const affiliate=new URLSearchParams(location.search).get('affiliate');if(affiliate)el('affiliateCode').value=affiliate;await loadMember();await loadCatalog();go(location.hash.slice(1)||'shop')}
async function submit(form,fn){const b=form.querySelector('button[type="submit"],button:not([type])');if(b){b.disabled=true;b.dataset.old=b.textContent;b.textContent='Please wait…'}try{await fn()}catch(err){toast(err.message||'Something went wrong')}finally{if(b){b.disabled=false;b.textContent=b.dataset.old||'Submit'}}}
el('signupForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const {data,error}=await db.auth.signUp({email:el('signupEmail').value.trim(),password:el('signupPassword').value,options:{emailRedirectTo:location.origin+location.pathname,data:{full_name:el('fullName').value.trim(),phone:el('phone').value.trim(),country_code:'PK',referral_code:el('referralCode').value.trim()||null,terms_accepted:el('termsConsent').checked?'true':'false',terms_version:'phase1-terms-v1'}}}).catch(()=>({data:null,error:{message:'Could not create account'}}));
 /* Supabase Auth stores referral/profile details as user metadata. */
 if(error){toast(error.message);return}if(data.user&&data.session){const patch={full_name:el('fullName').value.trim(),phone:el('phone').value.trim(),country_code:'PK'};/* Profile is created by the database auth trigger. Contact fields can be set after login. */const {error:profileError}=await db.from('member_profiles').update(patch).eq('user_id',data.user.id);if(profileError)console.warn(profileError)}toast(data.session?'Account created. Welcome to MIO.':'Account created. Check your email to confirm, then sign in.');form.reset();if(data.session){session=data.session;await loadMember();go('wallet')}})});
el('loginForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const {data,error}=await db.auth.signInWithPassword({email:el('loginEmail').value.trim(),password:el('loginPassword').value});if(error)throw error;session=data.session;await loadMember();toast('You are signed in');go(isAdmin?'workspace':'wallet')})});
el('forgotPassword').addEventListener('click',()=>{el('ticketEmail').value=el('loginEmail').value;go('support')});
el('sendResetEmail').addEventListener('click',async()=>{const email=el('ticketEmail').value.trim();if(!email){toast('Enter your account email first');return}const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname+'#reset'});if(error)toast(error.message);else toast('If that account exists, a reset email has been sent')});
el('binaryPlacementForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!isAdmin)throw Error('Workspace access required');const side=el('binaryParent').value.trim()?el('binarySide').value:null;const {error}=await db.rpc('admin_place_binary_member',{p_member_code:el('binaryMember').value.trim(),p_parent_code:el('binaryParent').value.trim()||null,p_side:side});if(error)throw error;toast('Binary placement saved permanently');form.reset()})});
el('binaryCycleForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!isAdmin)throw Error('Workspace access required');const start=new Date(el('cycleStart').value+'+05:00'),end=new Date(el('cycleEnd').value+'+05:00');const {data,error}=await db.rpc('admin_close_binary_cycle',{p_cycle_code:el('cycleCode').value.trim(),p_starts_at:start.toISOString(),p_ends_at:end.toISOString(),p_timezone:'Asia/Karachi'});if(error)throw error;toast('Binary cycle posted: '+String(data).slice(0,8));form.reset()})});
el('accountBtn').addEventListener('click',async e=>{if(e.currentTarget.dataset.page==='signout'){await db.auth.signOut();session=null;profile=null;isAdmin=false;await loadMember();toast('Signed out')}});
el('sellerForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{if(!session){el('referralCode').value=el('sellerIntroducer').value.trim();el('phone').value=el('sellerPhone').value.trim();el('signupEmail').value=el('sellerEmail').value.trim();go('join');throw Error('Complete free account registration with this referral code, then submit your application')}const {error}=await db.rpc('submit_vendor_application',{p_business:el('businessName').value.trim(),p_email:el('sellerEmail').value.trim(),p_phone:el('sellerPhone').value.trim(),p_categories:el('sellerCategories').value.trim(),p_description:el('sellerDescription').value.trim(),p_proposed:0.20,p_introducer_code:null});if(error)throw error;toast('Application submitted. Watch here for your commission offer.');e.target.reset();await loadSellerAgreement()})});
el('productForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,send=e.submitter?.value!=='draft';submit(form,async()=>{if(!session||!selectedVendor)throw Error('Select your approved store first');const vendor=el('productVendor').value;const images=await uploadListingPhotos(vendor);const {error}=await db.rpc('save_product_listing',{p_product_id:el('editingProduct').value||null,p_vendor_id:vendor,p_name:el('prodName').value.trim(),p_sku:el('prodSku').value.trim(),p_description:el('prodDescription').value.trim(),p_category:el('prodCategory').value.trim(),p_price:Number(el('prodPrice').value),p_stock:Number(el('prodStock').value),p_images:images,p_submit:send});if(error)throw error;toast(send?'Product sent for approval and PPV':'Draft saved');resetProductForm();await loadSellerProducts(vendor);if(isAdmin)await loadAdmin()})});
async function loadSellerProducts(vendor){const uid=session?.user.id;const {data,error}=await db.from('products').select('*').eq('vendor_id',vendor).order('created_at',{ascending:false});if(error)throw error;if(session?.user.id!==uid)return;el('sellerListings').innerHTML=data?.length?data.map(p=>`<div class="list-row"><div><strong>${esc(p.name)}</strong><small>${money(p.price_pkr)} · ${p.stock_quantity} stock · ${esc(p.status)}</small><form class="inventory-form form" data-id="${p.id}" data-vendor="${vendor}"><label>Price (PKR)<input type="number" name="price" min="0.01" step="0.01" value="${Number(p.price_pkr)}" required></label><label>Stock quantity (minimum entry: 200)<input type="number" name="stock" min="200" max="1000000" step="1" value="${p.stock_quantity}" required></label><button class="btn small">Save inventory</button></form></div><button class="btn small edit-listing" data-id="${p.id}">Edit details & photos</button></div>`).join(''):'<p>No listings in this store. Add your first product above.</p>'}
el('transferForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session)throw Error('Sign in first');const code=el('memberCode').value.trim();const recipient=await lookupRecipient(code);if(!recipient)throw Error('Confirm a valid recipient code first');if(isAdmin)await confirmSensitive('Send '+el('transferAmount').value+' MIO Points to '+recipient.full_name+' ('+recipient.member_code+')');const {error}=await db.rpc('mio_transfer_to_member_code',{p_recipient_code:recipient.member_code,p_amount:el('transferAmount').value,p_idempotency_key:idKey()});if(error)throw error;toast('MIO transfer recorded for '+recipient.full_name);form.reset();el('recipientPreview').textContent='Enter a code to confirm the recipient.';await loadMember()})});
document.addEventListener('click',e=>{const b=e.target.closest('.activate-package');if(b)submit({querySelector:()=>b},async()=>{if(!session){go('login');throw Error('Sign in to activate a package')}const {error}=await db.rpc('activate_package_with_mio',{p_package_code:b.dataset.code,p_idempotency_key:idKey()});if(error)throw error;toast('Package activated with MIO Points');await loadMember()});const copy=e.target.closest('.copy-code');if(copy)navigator.clipboard.writeText(copy.dataset.copy).then(()=>toast('Code copied'))});
el('checkoutForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session){el('cartModal').classList.remove('open');go('login');throw Error('Sign in before checkout')}const {data,error}=await db.rpc('place_affiliate_order',{p_affiliate_code:el('affiliateCode').value.trim()||null,p_items:[...cart.values()].map(x=>({product_id:x.product.id,quantity:x.qty})),p_shipping_name:el('shipName').value.trim(),p_shipping_phone:el('shipPhone').value.trim(),p_shipping_address:el('shipAddress').value.trim(),p_shipping_city:el('shipCity').value.trim(),p_idempotency_key:idKey()});if(error)throw error;cart.clear();updateCart();el('cartModal').classList.remove('open');toast('COD order placed. PPV waits for payment confirmation.');await loadMember();await loadCatalog();go('orders')})});
el('rateForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const {error}=await db.rpc('admin_set_usd_to_pkr_rate',{p_rate:Number(el('fxRate').value),p_reason:el('fxReason').value.trim()});if(error)throw error;toast('Conversion rate saved and audit logged');await loadCatalog()})});
el('adminMintForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Create '+el('mintAmount').value+' MIO Points in your company wallet. Reason: '+el('mintReason').value.trim());const {error}=await db.rpc('admin_mint_own_mio',{p_amount:Number(el('mintAmount').value),p_reason:el('mintReason').value.trim(),p_idempotency_key:idKey()});if(error)throw error;toast('MIO Points created in your wallet');form.reset();await loadMember()})});
el('adminBurnForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Remove '+el('burnAmount').value+' MIO Points from your company wallet. Reason: '+el('burnReason').value.trim());const {error}=await db.rpc('admin_burn_own_mio',{p_amount:Number(el('burnAmount').value),p_reason:el('burnReason').value.trim(),p_idempotency_key:idKey()});if(error)throw error;toast('MIO Points removed from your wallet');form.reset();await loadMember()})});
async function loadAdmin(){if(!isAdmin)return;const uid=session?.user.id;const responses=await Promise.all([db.from('vendor_applications').select('*').eq('status','pending').order('created_at'),db.from('products').select('*').order('created_at'),db.from('vendors').select('*').order('created_at'),db.from('orders').select('*').order('created_at',{ascending:false}).limit(100),db.from('featured_products').select('product_id,position').order('position')]);const failure=responses.find(x=>x.error)?.error;if(failure)throw failure;if(!isAdmin||session?.user.id!==uid)return;const [{data:apps},{data:ps},{data:vendors},{data:orders},{data:feats}]=responses;adminProductRows=ps||[];adminVendorRows=vendors||[];
 el('adminApplications').innerHTML=apps?.length?apps.map(a=>`<article class="review-card"><h3>${esc(a.business_name)}</h3><p>${esc(a.contact_email)} · ${esc(a.contact_phone)} · ${esc(a.categories)}</p><p>${esc(a.description)}</p><p>Vendor proposed: ${a.proposed_commission==null?'Legacy application':(a.proposed_commission*100).toFixed(2)+'%'} · ${a.agreement_accepted_at?'Vendor accepted '+(a.agreed_commission*100).toFixed(2)+'%':a.offered_commission!=null?'Awaiting vendor acceptance':'No offer sent yet'}</p><form class="vendor-offer form" data-id="${a.id}"><label>Final commission (% of sale)<input name="rate" class="approval-commission" data-id="${a.id}" type="number" min="5" max="100" step="0.0001" value="${Number(a.agreed_commission??a.offered_commission??a.proposed_commission??0)*100}" required></label><label>Agreement / payout terms<textarea name="note" minlength="5" required>${esc(a.terms_note||'')}</textarea></label><button class="btn">Send terms to vendor</button><p class="helper">The vendor accepts these terms in Sell with us. You can then approve the account.</p></form><button class="btn primary review-vendor" data-id="${a.id}" data-approve="true" ${a.proposed_commission!=null&&!a.agreement_accepted_at?'disabled':''}>Approve agreed application</button> <button class="btn review-vendor" data-id="${a.id}" data-approve="false">Reject application</button></article>`).join(''):'<p>No seller requests awaiting review.</p>';
 el('companyVendors').innerHTML=adminVendorRows.map(v=>`<article class="review-card"><div class="brand-heading">${safeImage(v.logo_url)?`<img src="${safeImage(v.logo_url)}" alt="${esc(v.business_name)} logo">`:''}<div><h3>${esc(v.business_name)}</h3><p>${esc(v.status)} · ${v.is_company_owned?'Company brand · sale funding managed below':(Number(v.commission_rate||0)*100).toFixed(2)+'% agreed commission'}</p></div></div>${`<form class="vendor-commission form" data-id="${v.id}"><label>Agreed commission (%)<input type="number" min="5" max="100" step="0.0001" value="${Number(v.commission_rate||0)*100}" required></label><button class="btn small">Save agreed commission</button><p class="helper">After changing the agreed rate, select this vendor in Commission & payouts to assign the remaining sale percentages. Previous orders keep their saved rate.</p></form>`}<button class="btn vendor-status" data-id="${v.id}" data-status="${v.status==='active'?'suspended':'active'}">${v.status==='active'?'Pause selling':'Resume selling'}</button> <button class="btn manage-brand" data-id="${v.id}">Manage products</button></article>`).join('')||'<p>No stores created yet.</p>';
 renderAdminProducts();const owned=new Set(adminVendorRows.filter(v=>v.is_company_owned).map(v=>v.id));const companyProducts=adminProductRows.filter(p=>p.status==='approved'&&owned.has(p.vendor_id));featuredIds=(feats||[]).map(f=>f.product_id);el('featuredChecks').innerHTML=companyProducts.length?companyProducts.map(p=>`<label class="feature-choice">${safeImage(p.image_url)?`<img src="${safeImage(p.image_url)}" alt="">`:''}<span><input type="checkbox" name="featured" value="${p.id}" ${featuredIds.includes(p.id)?'checked':''}> ${esc(p.name)}<small>${esc(adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name)}</small></span></label>`).join(''):'<p>Approve company-brand products first, then choose up to six here.</p>';
 el('adminOrders').innerHTML=orders?.length?orders.map(o=>`<article class="review-card"><h3>${esc(o.order_code)} · ${money(o.total_pkr)}</h3><p>Buyer discount: ${money(o.discount_pkr)} · ${esc(o.payment_status)} · ${esc(o.status)}</p><p>${esc(o.shipping_name)} · ${esc(o.shipping_phone)}<br>${esc(o.shipping_address)} · ${esc(o.shipping_city)}</p>${o.payment_status==='unconfirmed'&&!['cancelled','returned'].includes(o.status)?`<button class="btn primary confirm-order" data-id="${o.id}">Confirm received payment & award PPV</button> ${['placed','confirmed','processing'].includes(o.status)?`<button class="btn cancel-order" data-id="${o.id}">Cancel unpaid order & restore stock</button>`:''}`:''} ${['placed','confirmed','processing','shipped'].includes(o.status)?`<button class="btn advance-order" data-id="${o.id}" data-status="${{placed:'confirmed',confirmed:'processing',processing:'shipped',shipped:'delivered'}[o.status]}">Mark ${{placed:'confirmed',confirmed:'processing',processing:'shipped',shipped:'delivered'}[o.status]}</button>`:''}</article>`).join(''):'<p>No orders yet.</p>';
 el('workspaceOverview').innerHTML=[['Seller requests',apps?.length||0,'vendors'],['Products to review',adminProductRows.filter(p=>['draft','pending'].includes(p.status)).length,'products'],['Unconfirmed payments',(orders||[]).filter(o=>o.payment_status==='unconfirmed'&&!['cancelled','returned'].includes(o.status)).length,'orders'],['Company brands',owned.size,'brands']].map(([label,n,key])=>`<button class="card metric" data-workspace="${key}"><span>${label}</span><b>${n}</b><small>Open ${label.toLowerCase()}</small></button>`).join('');
 await loadCommissionReport();
}
function renderAdminProducts(){const search=el('reviewSearch').value.toLowerCase(),filter=el('reviewFilter').value;const rows=adminProductRows.filter(p=>(filter==='all'||(filter==='review'?['draft','pending','rejected'].includes(p.status):p.status===filter))&&(!search||[p.name,adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name].join(' ').toLowerCase().includes(search)));el('adminProducts').innerHTML=rows.map(p=>`<article class="review-card"><div class="review-product-head">${safeImage(p.image_url)?`<img src="${safeImage(p.image_url)}" alt="${esc(p.name)}">`:'<div class="missing-photo">Photo needed</div>'}<div><h3>${esc(p.name)}</h3><p>${esc(adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name)} · ${retailPriceLabel(p)}${money(p.price_pkr)} · ${p.stock_quantity} in stock · ${esc(p.status)}</p>${p.review_note?`<p class="note warn">${esc(p.review_note)}</p>`:''}<p>${esc(p.description).slice(0,500)}</p>${p.source_url?`<a href="${safeImage(p.source_url)}" target="_blank" rel="noopener">Original product</a>`:''}</div></div><button class="btn edit-listing" data-id="${p.id}">Edit details, photos, price & stock</button> ${p.status!=='approved'?`<label>PPV awarded per item<input class="approval-ppv" data-id="${p.id}" type="number" min="0" max="1000000" step="0.0001" value="${p.ppv_per_unit??''}" ${adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name==='Allure Care'?'readonly':''} required></label><button class="btn primary review-product" data-id="${p.id}" data-approve="true">Approve & publish with this PPV</button> <button class="btn review-product" data-id="${p.id}" data-approve="false">Reject</button>`:''} <button class="btn archive-listing" data-id="${p.id}">Archive / remove from shop</button>${adminVendorRows.find(v=>v.id===p.vendor_id)?.business_name==='Allure Care'?`<p class="note">Company 5%: ${money(Number(p.price_pkr)*0.05)} · Network funding 25%: ${money(Number(p.price_pkr)*0.25)} · BV: ${(Math.floor(Number(p.price_pkr)*0.25/300*10000)/10000).toFixed(4)} · Fixed PPV: ${(Math.floor(Number(p.price_pkr)*0.25/300*0.90*10000)/10000).toFixed(4)}. 1 point = PKR 300; PPV is personal activation only.</p>`:''}<p class="helper">Editing returns a listing to review. Allure Care PPV follows its sale-price formula automatically. Approval still requires a photo, positive price and available stock.</p></article>`).join('')||'<p>No products match this view.</p>'}
el('featuredForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const ids=[...document.querySelectorAll('input[name="featured"]:checked')].map(x=>x.value);if(ids.length>6)throw Error('Choose no more than six');const {error}=await db.rpc('set_featured_products',{p_product_ids:ids});if(error)throw error;toast('Featured products saved');loadCatalog();loadAdmin()})});el('reloadAdmin').addEventListener('click',()=>Promise.all([loadAdmin(),loadTickets()]).catch(e=>toast(e.message)));
boot().catch(err=>{console.error(err);toast('The page opened, but some data did not load.')});

async function fetchAll(table,columns,uid,field){let rows=[],offset=0;for(;;){const {data,error}=await db.from(table).select(columns).eq(field,uid).order('id').range(offset,offset+999);if(error)throw error;rows.push(...(data||[]));if(!data||data.length<1000)return rows;offset+=1000}}
el('resetForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session)throw Error('Open your password reset email first');if(isAdmin)throw Error('Change your password in the verified workspace');if(el('resetPassword').value!==el('resetConfirm').value)throw Error('Passwords do not match');const {error}=await db.auth.updateUser({password:el('resetPassword').value});if(error)throw error;form.reset();toast('Password updated');go('wallet')})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'))});

function safeImage(url){try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):''}catch{return ''}}
function renderProduct(id){const p=products.find(x=>x.id===id);if(!p){el('productDetail').innerHTML='<div class="empty-card empty"><h2>Product unavailable</h2><p>This product may be out of stock or no longer available.</p><button class="btn primary" data-page="shop">Browse marketplace</button></div>';return}const image=safeImage(p.image_url);el('productDetail').innerHTML=`<article class="card product-detail"><div class="detail-image">${image?`<img src="${image}" alt="${esc(p.name)}">`:'<div class="empty">Product image unavailable</div>'}</div><div class="card-body"><span class="pill">${esc(p.category||'Marketplace')}</span><h1>${esc(p.name)}</h1><p class="seller-name">${safeImage(p.vendors?.logo_url)?`<img class="seller-brand-logo" src="${safeImage(p.vendors.logo_url)}" alt="${esc(p.vendors.business_name)} logo">`:''}${esc(p.vendors?.business_name||'Approved store')}</p><p class="detail-price">${retailPriceLabel(p)}${money(p.price_pkr)}</p>${p.ppv_per_unit!==null&&p.ppv_per_unit!==undefined?`<p class="note">Earn ${Number(p.ppv_per_unit).toFixed(4)} PPV per item after payment confirmation.</p>`:''}<div class="product-gallery">${(p.image_urls||[]).filter(u=>safeImage(u)).map(u=>`<button class="btn small gallery-photo" data-url="${safeImage(u)}"><img src="${safeImage(u)}" alt="${esc(p.name)} photo"></button>`).join('')}</div><p class="detail-description">${esc(p.description)}</p><p class="helper">${p.stock_quantity} available · Cash on delivery</p>${session&&profile?`<button class="btn share-product" data-id="${p.id}">Copy my selling link</button><p class="helper">Affiliate commission: ${Number(p.vendors?.sale_distribution?.affiliate||0).toFixed(4)}% of sale · ${money(Number(p.price_pkr)*Number(p.vendors?.sale_distribution?.affiliate||0)/100)} per item. ${hasApprovedPackage?'Package active.':'Earnings and reward PPV/BV stay on hold until you activate a package.'}</p>`:''}<button class="btn primary add-cart" data-id="${p.id}">Add to basket</button></div></article>`;}

document.addEventListener('keydown',e=>{const modal=el('cartModal');if(e.key==='Tab'&&modal.classList.contains('open')){const controls=[...modal.querySelectorAll('button,input,textarea,select,a[href]')].filter(n=>!n.disabled&&!n.closest('.hidden'));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});

let enrollmentId=null,actionResolver=null,googleEnabled=false;
function clearSecurity(){enrollmentId=null;el('totpQr').removeAttribute('src');el('totpSecret').textContent='';el('totpSetup').classList.add('hidden');el('totpCode').value='';el('actionCode').value='';el('operatorPasswordForm').reset();if(actionResolver){actionResolver.reject(Error('Signed out'));actionResolver=null;el('verifyActionDialog').close()}}
async function verifiedFactor(){const {data,error}=await db.auth.mfa.listFactors();if(error)throw error;return data.totp.find(f=>f.status==='verified')}
async function verifyCode(code,factorId){if(!session)throw Error('Sign in first');if(!/^[0-9]{6}$/.test(code))throw Error('Enter the current 6-digit code');const factor=factorId||((await verifiedFactor())?.id);if(!factor)throw Error('Set up your authenticator in Security first');const {error}=await db.auth.mfa.challengeAndVerify({factorId:factor,code});if(error)throw error;const {data}=await db.auth.getSession();session=data.session||session}
async function confirmSensitive(summary){if(!isAdmin)throw Error('Workspace access required');if(!await verifiedFactor()){go('security');throw Error('Set up your authenticator before using these controls')}if(actionResolver)throw Error('Complete the current confirmation first');el('verifyActionSummary').textContent=summary;el('actionCode').value='';el('actionError').textContent='';el('verifyActionDialog').showModal();el('actionCode').focus();return new Promise((resolve,reject)=>{actionResolver={resolve,reject}})}
function cancelSensitive(){if(actionResolver){actionResolver.reject(Error('Action cancelled'));actionResolver=null}el('verifyActionDialog').close();el('actionCode').value=''}
el('cancelAction').addEventListener('click',cancelSensitive);el('verifyActionDialog').addEventListener('cancel',e=>{e.preventDefault();cancelSensitive()});
el('verifyActionForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{try{await verifyCode(el('actionCode').value.trim());const pending=actionResolver;actionResolver=null;el('verifyActionDialog').close();el('actionCode').value='';pending?.resolve()}catch(error){el('actionError').textContent=error.message;throw error}})});
el('enrollTotp').addEventListener('click',async()=>{try{if(!session)throw Error('Sign in first');if(await verifiedFactor())throw Error('Your authenticator is already enabled. Enter its current code below.');if(enrollmentId){el('totpSetup').classList.remove('hidden');return}const {data,error}=await db.auth.mfa.enroll({factorType:'totp',friendlyName:'MIO authenticator'});if(error)throw error;enrollmentId=data.id;el('totpQr').src=data.totp.qr_code;el('totpSecret').textContent=data.totp.secret;el('totpSetup').classList.remove('hidden')}catch(error){toast(error.message)}});
el('verifyTotpForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{await verifyCode(el('totpCode').value.trim(),enrollmentId);enrollmentId=null;el('totpSetup').classList.add('hidden');el('totpSecret').textContent='';el('totpQr').removeAttribute('src');el('totpCode').value='';el('totpStatus').textContent='Authenticator verified. Keep access to your authenticator app.';await loadMember()})});
