document.addEventListener('submit',e=>{if(!e.target.matches('.vendor-commission'))return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.rpc('set_vendor_commission',{p_vendor_id:form.dataset.id,p_rate:Number(form.querySelector('input').value)/100});if(error)throw error;toast('Seller commission saved');await loadAdmin()})});
let operationsMembers=[];
const exportKeys={shopping_reward_events:'order_id',commission_allocations:'id',vendor_applications:'id',premium_purchase_requests:'id',member_profiles:'user_id',binary_placements:'member_id',vendor_income_ledger:'id',vendor_withdrawals:'id',vendors:'id',products:'id',package_versions:'package_code',system_config:'config_key',package_activations:'id',point_ledger:'id',mio_wallet_accounts:'member_id',mio_ledger:'id',bonus_transactions:'id',binary_cycles:'id',binary_member_results:'cycle_id',orders:'id',order_items:'id',audit_logs:'id'};
async function readDataset(table){if(!isAdmin||!exportKeys[table])throw Error('Workspace access required');let rows=[],offset=0;for(;;){const {data,error}=await db.from(table).select('*').order(exportKeys[table]).order(table==='package_versions'||table==='system_config'?'version':table==='binary_member_results'?'member_id':exportKeys[table]).range(offset,offset+999);if(error)throw error;if(!isAdmin)throw Error('Session ended');rows.push(...(data||[]));if(!data||data.length<1000)return rows;offset+=1000}}
function showOperationsMembers(){const search=el('memberSearch').value.trim().toLowerCase();const rows=operationsMembers.filter(m=>[m.full_name,m.member_code,m.referral_code].some(v=>String(v||'').toLowerCase().includes(search))).slice(0,100);el('workspaceMembers').innerHTML=rows.length?`<table><thead><tr><th>Member</th><th>Code</th><th>Status</th><th>Sponsor</th><th>Joined</th><th>Manage</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.full_name)}</td><td>${esc(m.member_code)}</td><td>${esc(m.status)}</td><td>${esc(operationsMembers.find(s=>s.user_id===m.sponsor_id)?.member_code||'—')}</td><td>${new Date(m.created_at).toLocaleDateString()}</td><td><button class="btn small edit-member" data-id="${m.user_id}">Edit account</button></td></tr>`).join('')}</tbody></table><p class="helper">Showing up to 100 matches. Exports include all records.</p>`:'<p>No matching members.</p>'}
async function loadOperationsMembers(){operationsMembers=await readDataset('member_profiles');showOperationsMembers()}
async function loadOperationsReport(){if(!isAdmin)return;const {data,error}=await db.rpc('operations_report');if(error)throw error;if(!isAdmin)return;el('operationsReport').innerHTML=`<table><tbody>${Object.entries(data||{}).map(([key,value])=>`<tr><th>${esc(key.replaceAll('_',' '))}</th><td>${esc(typeof value==='object'?JSON.stringify(value):String(value))}</td></tr>`).join('')}</tbody></table>`}
el('memberSearch').addEventListener('input',showOperationsMembers);el('refreshReport').addEventListener('click',()=>loadOperationsReport().catch(e=>toast(e.message)));
function exportText(rows,format){if(format==='json')return JSON.stringify(rows,null,2);const keys=[...new Set(rows.flatMap(row=>Object.keys(row)))];const cell=value=>{let text=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};return [keys.map(cell).join(','),...rows.map(row=>keys.map(key=>cell(row[key])).join(','))].join('\r\n')}
el('exportForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const dataset=el('exportDataset').value,format=el('exportFormat').value;const rows=await readDataset(dataset);const blob=new Blob([exportText(rows,format)],{type:format==='json'?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mio-'+dataset+'-'+new Date().toISOString().slice(0,10)+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded: '+rows.length+' records')})});
document.addEventListener('submit',e=>{if(!e.target.matches('.inventory-form'))return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.rpc('update_seller_inventory',{p_product_id:form.dataset.id,p_price:Number(form.elements.price.value),p_stock:Number(form.elements.stock.value)});if(error)throw error;toast('Inventory saved. Price changes require listing review.');await loadSellerProducts(form.dataset.vendor);await loadCatalog()})});
document.addEventListener('click',e=>{const cancel=e.target.closest('.cancel-order');if(cancel)submit({querySelector:()=>cancel},async()=>{const {error}=await db.rpc('cancel_unpaid_order',{p_order_id:cancel.dataset.id});if(error)throw error;toast('Order cancelled and stock restored');await loadMember();await loadCatalog()});const advance=e.target.closest('.advance-order');if(advance)submit({querySelector:()=>advance},async()=>{const {error}=await db.rpc('advance_order_status',{p_order_id:advance.dataset.id,p_status:advance.dataset.status});if(error)throw error;toast('Fulfillment status updated');await loadAdmin()})});
async function loadOfflineInstructions(){const {data,error}=await db.from('system_config').select('config_value').eq('config_key','OFFLINE_PAYMENT').is('effective_to',null).order('version',{ascending:false}).limit(1);if(error)throw error;const text=data?.[0]?.config_value?.instructions||'';el('offlinePaymentInstructions').textContent=text||'The company has not provided payment instructions yet. Do not send a payment until they are published.';el('premiumPurchaseForm').querySelector('button').disabled=!text}
el('premiumPurchaseForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session){go('login');throw Error('Sign in first')}const {error}=await db.rpc('request_offline_premium_purchase',{p_reference:el('premiumPaymentRef').value.trim(),p_details:el('premiumPaymentDetails').value.trim(),p_idempotency_key:idKey()});if(error)throw error;form.reset();toast('Payment submitted for verification. Premium remains pending.');await loadPremiumPurchases()})});
async function loadPremiumPurchases(){if(!session)return;const uid=session.user.id;const {data,error}=await db.from('premium_purchase_requests').select('id,expected_pkr,payment_reference,status,review_note,created_at').eq('member_id',uid).order('created_at',{ascending:false}).limit(50);if(error)throw error;if(!session||session.user.id!==uid)return;el('premiumPurchaseHistory').innerHTML=data?.length?data.map(r=>`<div class="list-row"><div><strong>${esc(r.payment_reference)} · ${money(r.expected_pkr)}</strong><small>${new Date(r.created_at).toLocaleString()}${r.review_note?' · '+esc(r.review_note):''}</small></div><span class="pill">${esc(r.status)}</span></div>`).join(''):'<p>No offline Premium purchase requests.</p>'}
async function loadPremiumApprovals(){if(!isAdmin)return;const {data,error}=await db.from('premium_purchase_requests').select('*').eq('status','pending').order('created_at');if(error)throw error;if(!isAdmin)return;el('premiumPurchaseApprovals').innerHTML=data?.length?data.map(r=>`<form class="form premium-approval" data-id="${r.id}" data-amount="${r.expected_pkr}"><strong>${esc(operationsMembers.find(m=>m.user_id===r.member_id)?.member_code||r.member_id)} · ${money(r.expected_pkr)} · ${r.mio_amount} MIO</strong><p>${esc(r.payment_reference)}</p><p>${esc(r.payment_details)}</p><label>Decision<select name="decision"><option value="approve">Approve verified payment</option><option value="reject">Reject</option></select></label><label>Amount verified in company payment records (PKR)<input name="verified" type="number" min="0" step="0.01"></label><label>Verification or rejection note<textarea name="note" minlength="20" maxlength="2000" required></textarea></label><button class="btn primary">Verify & submit decision</button></form>`).join(''):'<p>No Premium payments awaiting verification.</p>';el('premiumPurchaseApprovals').querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();submit(form,async()=>{const approve=form.elements.decision.value==='approve';await confirmSensitive((approve?'Approve':'Reject')+' this Premium purchase. Expected payment: '+money(form.dataset.amount));const {error}=await db.rpc('review_offline_premium_purchase',{p_request_id:form.dataset.id,p_approve:approve,p_verified_pkr:approve?Number(form.elements.verified.value):null,p_note:form.elements.note.value.trim()});if(error)throw error;toast(approve?'Verified MIO purchase completed and Premium activated':'Purchase request rejected');await loadMember()})}))}
el('offlineInstructionsForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const {error}=await db.rpc('set_offline_payment_instructions',{p_instructions:el('companyPaymentInstructions').value.trim()});if(error)throw error;toast('Company payment instructions published');await loadOfflineInstructions()})});

// Network exploration, verified recipient preview and seller account.
let networkRoot=null,networkHistory=[],networkRequest=0,recipientRequest=0;
function clearNetworkViews(){networkRequest++;recipientRequest++;networkRoot=null;networkHistory=[];['networkVisual','sellerSummary','sellerSales','sellerWithdrawals','withdrawalApprovals','companyNetworkSummary'].forEach(id=>el(id).replaceChildren());el('sellerNav').classList.add('hidden');el('recipientPreview').textContent='Enter a code to confirm the recipient.';el('vendorWithdrawalForm').reset()}
async function lookupRecipient(code){const turn=++recipientRequest,uid=session?.user.id;el('recipientPreview').textContent='Checking recipient…';const {data,error}=await db.rpc('lookup_transfer_recipient',{p_code:code});if(turn!==recipientRequest||session?.user.id!==uid)return null;if(error){el('recipientPreview').textContent='Could not verify recipient.';throw error}const recipient=data?.[0];el('recipientPreview').textContent=recipient?recipient.full_name+' · '+recipient.member_code:'No active recipient found.';return recipient}
let recipientTimer;el('memberCode').addEventListener('input',()=>{recipientRequest++;clearTimeout(recipientTimer);el('recipientPreview').textContent='Enter a code to confirm the recipient.';const code=el('memberCode').value.trim();if(code.length>=5)recipientTimer=setTimeout(()=>lookupRecipient(code).catch(e=>toast(e.message)),300)});
let sponsorTimer,sponsorRequest=0;async function previewSponsor(){const turn=++sponsorRequest;const {data,error}=await db.rpc('lookup_side_referral',{p_code:el('referralCode').value.trim()});if(turn!==sponsorRequest)return;el('signupSponsor').textContent=error?'Could not verify referral':data?.[0]?data[0].full_name+' · '+(data[0].placement_side||'Use the inviter’s LEFT/RIGHT code'):'Referral not found. Use a team member’s code.'}
el('referralCode').addEventListener('input',()=>{sponsorRequest++;clearTimeout(sponsorTimer);sponsorTimer=setTimeout(()=>previewSponsor().catch(e=>toast(e.message)),300)});if(incomingReferral)previewSponsor().catch(e=>toast(e.message));
function approvalValue(selector,id,required,divisor){if(!required)return null;const input=document.querySelector(selector+'[data-id="'+id+'"]');if(!input||input.value===''||!input.checkValidity()){toast('Enter the required approval value first');return null}return Number(input.value)/divisor}
async function loadNetworkViews(){if(!session||!profile)return;const links=isAdmin?'<p>Company has one direct founder: Abdul Rehman. Company has no LEFT/RIGHT referral links.</p>':['LEFT','RIGHT'].map(side=>{const code=profile.referral_code+'-'+side[0],url=location.origin+location.pathname+'?ref='+encodeURIComponent(code)+'#join';return `<section class="referral-tile"><h3>${side} referral</h3><p class="code">${esc(code)}</p><p class="referral-url">${esc(url)}</p><button class="btn small copy-code" data-copy="${esc(code)}">Copy code</button> <button class="btn primary small copy-code" data-copy="${esc(url)}">Copy link</button><small>Joins your ${side.toLowerCase()}most line. You remain the sponsor.</small></section>`}).join('');el('profileCard').innerHTML=`<h3>${esc(profile.full_name)}</h3><p class="code">${esc(profile.member_code)}</p><div class="referral-links">${links}</div>`;await renderNetwork()}
async function renderNetwork(){if(!session)return;const turn=++networkRequest,uid=session.user.id,kind=el('networkKind').value;el('networkVisual').textContent='Loading your network…';const {data,error}=await db.rpc('my_network',{p_kind:kind,p_root_code:networkRoot,p_depth:Number(el('networkDepth').value)});if(turn!==networkRequest||session?.user.id!==uid)return;if(error){el('networkVisual').textContent='Could not load network.';throw error}const nodes=data?.nodes||[];el('networkExplanation').textContent=({generation:'Direct sponsor relationships. Placement does not change the inviter.',binary:'LEFT and RIGHT placement. Company is outside the tree; Abdul Rehman is its root.',pool:'Same binary positions, with package BP and available left/right volume. 50 BP on each side completes one share.',single_line:'Placement ancestors determine single-line income. Package limits: 10 / 15 / 20 / 25 / 30 levels.',vendor:'One level of referred vendors.'})[kind];el('networkBack').disabled=!networkHistory.length;
const card=n=>`<button class="tree-node" data-tree-root="${esc(n.member_code)}"><strong>${esc(n.full_name)}</strong><small>${esc(n.member_code)}${n.side?' · '+esc(n.side):''}</small><span>${esc(n.package||n.status||'Free')}</span>${kind==='pool'?`<b>${Number(n.bp||0)} package BP</b><small>Left ${Number(n.left_bp||0).toFixed(4)} · Right ${Number(n.right_bp||0).toFixed(4)}</small><small>${Math.floor(Math.min(Number(n.left_bp||0),Number(n.right_bp||0))/50)} complete shares</small>`:''}</button>`;
if(kind==='vendor'){el('networkVisual').innerHTML=nodes.length?'<div class="vendor-tree">'+nodes.map(n=>`<div class="tree-node"><strong>${esc(n.full_name)}</strong><small>${esc(n.member_code)} · ${esc(n.status)}</small></div>`).join(''):'<p>No directly referred vendors yet.</p>';return}
const children=new Map();for(const n of nodes){const key=n.parent_id||'root';if(!children.has(key))children.set(key,[]);children.get(key).push(n)}const branch=(n,depth=0)=>{if(depth>6)return '';const kids=children.get(n.id)||[];return `<li>${card(n)}${kids.length?'<ul>'+kids.map(k=>branch(k,depth+1)).join('')+'</ul>':''}</li>`};const roots=nodes.filter(n=>n.depth===0);el('networkVisual').innerHTML=roots.length?'<ul class="network-tree">'+roots.map(n=>branch(n)).join('')+'</ul>'+(data.truncated?'<p>Showing up to 500 members. Select a member to explore their subtree.</p>':''):'<p>Your binary position has not been assigned yet. Contact operations.</p>'}
el('networkKind').addEventListener('change',()=>{networkRoot=null;networkHistory=[];renderNetwork().catch(e=>toast(e.message))});el('networkDepth').addEventListener('change',()=>renderNetwork().catch(e=>toast(e.message)));el('networkHome').addEventListener('click',()=>{networkRoot=null;networkHistory=[];renderNetwork().catch(e=>toast(e.message))});el('networkBack').addEventListener('click',()=>{networkRoot=networkHistory.pop()||null;renderNetwork().catch(e=>toast(e.message))});el('networkVisual').addEventListener('click',e=>{const b=e.target.closest('[data-tree-root]');if(b&&b.dataset.treeRoot!==networkRoot){networkHistory.push(networkRoot);networkRoot=b.dataset.treeRoot;renderNetwork().catch(e=>toast(e.message))}});
async function loadSellerAccount(vid){const uid=session?.user.id;const [summary,ledger,withdrawals]=await Promise.all([db.rpc('my_brand_summary',{p_vendor_id:vid}),db.from('vendor_income_ledger').select('*').eq('vendor_id',vid).order('created_at',{ascending:false}).limit(100),db.from('vendor_withdrawals').select('id,amount_pkr,status,review_note,created_at').eq('vendor_id',vid).order('created_at',{ascending:false}).limit(100)]);const error=[summary,ledger,withdrawals].find(r=>r.error)?.error;if(error)throw error;if(!session||session.user.id!==uid)return;const s=summary.data;if(!s)return;const available=Number(s.income_pkr)-Number(s.reserved_pkr)-Number(s.paid_pkr);el('sellerSummary').innerHTML=[['Confirmed sales',s.sales_pkr],['Your income',s.income_pkr],['Available to withdraw',available],['Reserved withdrawals',s.reserved_pkr],['Withdrawals paid',s.paid_pkr]].map(([title,value])=>`<section class="card metric"><span>${title}</span><b>${money(value)}</b></section>`).join('');el('sellerSales').innerHTML=ledger.data?.length?`<table><thead><tr><th>Date</th><th>Sale</th><th>Company commission</th><th>Your income</th></tr></thead><tbody>${ledger.data.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString()}</td><td>${money(r.gross_pkr)}</td><td>${money(r.commission_pkr)}</td><td>${money(r.net_pkr)}</td></tr>`).join('')}</tbody></table>`:'<p>No confirmed sales yet.</p>';el('sellerWithdrawals').innerHTML=withdrawals.data?.length?withdrawals.data.map(r=>`<div class="list-row"><strong>${money(r.amount_pkr)}</strong><span>${esc(r.status)}</span><small>${esc(r.review_note||'Awaiting company review')}</small></div>`).join(''):'<p>No withdrawal requests.</p>'}
el('vendorWithdrawalForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const {error}=await db.rpc('request_brand_withdrawal',{p_vendor_id:el('sellerBrand').value,p_amount:el('withdrawAmount').value,p_bank:el('withdrawBank').value.trim(),p_account_name:el('withdrawName').value.trim(),p_account_number:el('withdrawAccount').value.trim(),p_idempotency_key:idKey()});if(error)throw error;form.reset();toast('Withdrawal request sent to operations');await loadMember()})});
async function loadWithdrawalApprovals(){if(!isAdmin)return;const {data,error}=await db.from('vendor_withdrawals').select('*').in('status',['pending','approved']).order('created_at').limit(100);if(error)throw error;if(!isAdmin)return;el('withdrawalApprovals').innerHTML=data?.length?data.map(r=>`<form class="form withdrawal-review" data-id="${r.id}"><strong>${esc(adminVendorRows.find(v=>v.id===r.vendor_id)?.business_name||'Seller')} · ${money(r.amount_pkr)} · ${esc(r.status)}</strong><p>${esc(r.bank_name)} · ${esc(r.account_name)} · ${esc(r.account_number)}</p><label>Decision<select name="decision">${r.status==='pending'?'<option value="approved">Approve request</option>':'<option value="paid">Mark paid after bank payment</option>'}<option value="rejected">Reject / release reservation</option></select></label><label>Payment reference / decision note<textarea name="note" required minlength="10" maxlength="2000"></textarea></label><button class="btn primary">Verify & save decision</button></form>`).join(''):'<p>No seller withdrawals awaiting review.</p>'}
document.addEventListener('submit',e=>{if(!e.target.matches('.withdrawal-review'))return;e.preventDefault();const form=e.target;submit(form,async()=>{await confirmSensitive('Record seller withdrawal decision: '+form.elements.decision.value);const {error}=await db.rpc('review_vendor_withdrawal',{p_request_id:form.dataset.id,p_status:form.elements.decision.value,p_note:form.elements.note.value.trim()});if(error)throw error;toast('Withdrawal decision recorded');await loadWithdrawalApprovals()})});
async function loadCompanySummary(){const {data,error}=await db.rpc('company_network_summary');if(error)throw error;if(!isAdmin)return;el('companyNetworkSummary').innerHTML=`<p>Sole founder: <strong>${esc(data?.founder||'Not configured')}</strong></p><p>Binary company retention: ${Number(data?.binary_retention_mio||0).toFixed(4)} MIO</p><p>Package company fees: ${Number(data?.package_fees_mio||0).toFixed(4)} MIO</p><p>Company earnings from vendors: ${money(data?.seller_commission_pkr)}</p>`}
// One task section at a time, with plain-language guidance.
const workspace=el('page-admin'),heading=workspace.querySelector('.heading');workspace.prepend(heading);heading.querySelector('h1').textContent='Control centre';heading.querySelector('p').textContent='Choose a task below. Each section explains what it controls.';
const workspaceSections=[['home','Overview','Start here: open pending requests, review products and confirm received payments.'],['vendors','Seller requests','Read the application, send commission terms, wait for vendor acceptance, then approve or reject.'],['brands','Stores & company brands','Create company brands, pause or resume sellers and manage store products. Company brands have no commission.'],['products','Products & featured picks','Review every listing, set its PPV and publish it. Select up to six approved company products for the homepage.'],['orders','Orders & payments','Check delivery details, confirm genuine received payments and update delivery progress. PPV and earnings post once after confirmation.'],['commissions','Commission & payouts','Select a vendor, assign sale percentages, review company earnings and record verified payouts.'],['withdrawals','Seller withdrawals','Approve seller income withdrawals. Mark paid only after the actual bank payment. Rejection releases reserved funds.'],['premium','Premium payments','Publish payment instructions and verify offline Premium purchases against your company records.'],['members','Members & reports','Find member accounts, review totals and download complete records for reconciliation.'],['network','Network & weekly pool','Inspect permanent placements and settle completed weekly binary periods. Company has one direct founder, Abdul Rehman, and no LEFT or RIGHT position.'],['settings','Shipping, rates & security','Set the shipping charge and delivery policy, maintain the PKR/USD rate and change your password after authenticator verification.'],['wallet','Company wallet','Create or remove MIO Points in the company wallet with a recorded reason. Send existing points through Points & wallet.'],['support','Account support','Read recovery requests and save replies that ticket holders can view using their private tracking keys.']];
const shell=document.createElement('div');shell.className='control-shell';const nav=document.createElement('nav');nav.className='control-nav';nav.setAttribute('aria-label','Control centre tasks');const body=document.createElement('div');body.className='control-body';const panels=new Map();for(const [key,label,help] of workspaceSections){const b=document.createElement('button');b.className='btn';b.dataset.workspace=key;b.textContent=label;nav.append(b);const panel=document.createElement('section');panel.className='workspace-group control-panel hidden';panel.id='control-'+key;panel.innerHTML=`<h2>${label}</h2><p class="control-help">${help}</p>`;panels.set(key,panel);body.append(panel)}
const overview=document.createElement('div');overview.id='workspaceOverview';overview.className='layout cols2';panels.get('home').append(overview);
const assignments={commissionCard:'commissions',offlineInstructionsForm:'premium',workspaceMembers:'members',operatorPasswordForm:'settings',rateForm:'settings',adminMintForm:'wallet',adminApplications:'vendors',companyVendors:'brands',adminProducts:'products',binaryPlacementForm:'network',binaryCycleForm:'network',adminOrders:'orders',withdrawalApprovals:'withdrawals',companyNetworkSummary:'network',workspaceTickets:'support'};
// Move individual cards so previously paired controls are independent tasks.
for(const [id,key] of Object.entries(assignments)){const node=el(id);if(!node)continue;const card=node.matches('.card')?node:node.closest('.card');if(card)panels.get(key).append(card)}
workspace.append(shell);shell.append(nav,body);workspace.querySelectorAll(':scope > .layout').forEach(n=>{if(!n.children.length)n.remove()});
function showWorkspace(key){if(!panels.has(key))return;for(const [k,p] of panels)p.classList.toggle('hidden',k!==key);nav.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.workspace===key);b.setAttribute('aria-pressed',String(b.dataset.workspace===key))})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-workspace]');if(b)showWorkspace(b.dataset.workspace)});showWorkspace('home');
const splitLabels={company:'Company',buyer_discount:'Buyer discount',affiliate:'Selling affiliate',sponsor:'Affiliate sponsor',second_upline:'Sponsor’s sponsor',introducer:'Vendor introducer',network_rewards:'Shopping network budget',unallocated:'Unallocated / held'};
let currentSplit={company:5,buyer_discount:0,affiliate:0,sponsor:0,second_upline:0,introducer:0,network_rewards:0,unallocated:0};
function selectedDistributionVendor(){return adminVendorRows.find(v=>v.id===el('commissionVendor').value)}
function renderSplitInputs(){const v=selectedDistributionVendor();currentSplit=v?.sale_distribution||{...currentSplit};el('commissionSplitInputs').innerHTML=Object.entries(splitLabels).map(([key,label])=>`<label>${label} (% of sale)<input type="number" name="${key}" min="0" max="100" step="0.0001" value="${currentSplit[key]??0}" ${key==='company'?'readonly':''} required></label>`).join('');updateSplitTotal()}
function updateSplitTotal(){const v=selectedDistributionVendor();const total=[...el('commissionSplitInputs').querySelectorAll('input')].reduce((n,x)=>n+Number(x.value),0);const agreed=Number(v?.commission_rate||0)*100;el('commissionSplitTotal').textContent=`Total: ${total.toFixed(4)}% of sale · Agreed commission: ${agreed.toFixed(4)}% · Remaining to assign: ${(agreed-total).toFixed(4)}%`;el('commissionSplitForm').querySelector('button').disabled=!v||Math.abs(total-agreed)>0.000001||agreed<5;const price=Number(el('distributionExamplePrice').value||100);el('distributionPreview').textContent=`On a ${money(price)} sale: company ${money(price*0.05)} · seller proceeds ${money(price*(1-agreed/100))} · remaining distribution budget ${money(price*Math.max(agreed-5,0)/100)}. `+[...el('commissionSplitInputs').querySelectorAll('input')].filter(x=>x.name!=='company'&&Number(x.value)>0).map(x=>`${splitLabels[x.name]}: ${money(price*Number(x.value)/100)}`).join(' · ')}
el('commissionVendor').addEventListener('change',renderSplitInputs);
el('distributionExamplePrice').addEventListener('input',updateSplitTotal);
el('commissionSplitInputs').addEventListener('input',updateSplitTotal);
el('commissionSplitForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const split=Object.fromEntries([...el('commissionSplitInputs').querySelectorAll('input')].map(x=>[x.name,Number(x.value)]));const v=selectedDistributionVendor();if(!v)throw Error('Select a vendor');await confirmSensitive('Save sale percentages for '+v.business_name);const {error}=await db.rpc('set_vendor_sale_distribution',{p_vendor_id:v.id,p_split:split});if(error)throw error;toast('Vendor sale distribution saved');await loadAdmin();await loadCatalog()})});
async function loadCommissionReport(){const uid=session?.user.id;const [earnings,allocs]=await Promise.all([db.rpc('vendor_company_earnings'),db.from('commission_allocations').select('*').order('created_at',{ascending:false}).limit(300)]);const failure=[earnings,allocs].find(r=>r.error)?.error;if(failure)throw failure;if(!isAdmin||session?.user.id!==uid)return;const previousVendor=el('commissionVendor').value;el('commissionVendor').innerHTML='<option value="">Select a vendor first</option>'+adminVendorRows.map(v=>`<option value="${v.id}">${esc(v.business_name)} · ${(Number(v.commission_rate)*100).toFixed(2)}% agreed</option>`).join('');el('commissionVendor').value=adminVendorRows.some(v=>v.id===previousVendor)?previousVendor:'';renderSplitInputs();el('vendorCompanyEarnings').innerHTML='<h3>Company earnings from vendors</h3><p>Confirmed sales only. Company share is 5% of merchandise sale; shipping is excluded.</p>'+((earnings.data||[]).map(v=>`<div class="list-row"><strong>${esc(v.business_name)}</strong><span>${money(v.company_earnings_pkr)}</span></div>`).join('')||'<p>No confirmed sales yet.</p>');const rows=allocs.data||[];el('commissionReport').innerHTML=`<h3>Commission records</h3><p>Earned: ${money(rows.filter(r=>r.status==='earned').reduce((n,r)=>n+Number(r.amount_pkr),0))} · Held: ${money(rows.filter(r=>r.status==='held').reduce((n,r)=>n+Number(r.amount_pkr),0))} · Showing latest ${rows.length} records. Export for complete totals.</p>`+(rows.length?rows.map(r=>`<div class="list-row"><div><strong>${esc(splitLabels[r.share_kind])} · ${money(r.amount_pkr)}</strong><small>${esc(r.status)} · ${esc(operationsMembers.find(m=>m.user_id===r.beneficiary_id)?.member_code||r.beneficiary_id||'Recipient not identified')} · Order item ${esc(r.order_item_id)}</small>${r.payment_reference?`<small>${esc(r.payment_reference)}</small>`:''}</div>${r.status==='held'&&!r.beneficiary_id&&!['company','buyer_discount','network_rewards','unallocated'].includes(r.share_kind)?`<form class="resolve-commission form" data-id="${r.id}"><label>Verified recipient member code<input name="code" required></label><label>How was this recipient verified?<textarea name="reason" minlength="20" required></textarea></label><button class="btn small">Verify & release held share</button></form>`:r.status==='earned'&&!['company','buyer_discount','network_rewards','unallocated'].includes(r.share_kind)?`<form class="commission-payment form" data-id="${r.id}"><label>Actual bank payment reference<input name="reference" minlength="10" required></label><button class="btn small">Verify & mark paid</button></form>`:''}</div>`).join(''):'<p>Records appear after confirmed vendor purchases.</p>')}
async function loadSellerAgreement(){updateSellerReferral();if(!session)return;const uid=session.user.id;const {data,error}=await db.from('vendor_applications').select('*').eq('applicant_user_id',session.user.id).order('created_at',{ascending:false}).limit(1);if(error)throw error;if(session?.user.id!==uid)return;const a=data?.[0];el('sellerAgreement').innerHTML=a?`<article class="review-card"><h3>Your application: ${esc(a.business_name)}</h3><p>Status: ${esc(a.status)}</p>${a.offered_commission!=null?`<p>Company offer: ${(a.offered_commission*100).toFixed(2)}% of product sale price.</p><p>${esc(a.terms_note)}</p>${a.agreement_accepted_at?'<p>Terms accepted. The company can now approve your store.</p>':a.status==='pending'?`<button class="btn primary accept-terms" data-id="${a.id}">Accept this commission and terms</button>`:''}`:'<p>The company will send its final commission offer here.</p>'}</article>`:'';el('sellerForm').classList.toggle('hidden',!!a);}
async function loadOwnedBrands(){if(!session)return;const uid=session.user.id;let q=db.from('vendors').select('id,business_name,status,owner_user_id,is_company_owned').eq('status','active');if(!isAdmin)q=q.eq('owner_user_id',session.user.id);const {data,error}=await q.order('created_at');if(error)throw error;if(session?.user.id!==uid)return;ownedBrands=data||[];if(!ownedBrands.some(v=>v.id===selectedVendor))selectedVendor=ownedBrands[0]?.id||null;for(const id of ['productVendor','sellerBrand']){el(id).innerHTML=ownedBrands.map(v=>`<option value="${v.id}">${esc(v.business_name)}</option>`).join('');el(id).value=selectedVendor||''}el('sellerProducts').classList.toggle('hidden',!selectedVendor);el('sellerNav').classList.toggle('hidden',!selectedVendor);if(selectedVendor){await loadSellerProducts(selectedVendor);await loadSellerAccount(selectedVendor)}el('vendorWithdrawalForm').classList.toggle('hidden',!ownedBrands.find(v=>v.id===selectedVendor&&v.owner_user_id===session.user.id))}
for(const id of ['productVendor','sellerBrand'])el(id).addEventListener('change',async e=>{selectedVendor=e.target.value;resetProductForm();el('productVendor').value=selectedVendor;el('sellerBrand').value=selectedVendor;try{await loadSellerProducts(selectedVendor);await loadSellerAccount(selectedVendor);el('vendorWithdrawalForm').classList.toggle('hidden',!ownedBrands.find(v=>v.id===selectedVendor&&v.owner_user_id===session.user.id))}catch(err){toast(err.message)}});
function clearListingPhotos(){for(const p of listingPhotos)if(p.preview?.startsWith('blob:'))URL.revokeObjectURL(p.preview);listingPhotos=[];renderPhotoPreview()}
function resetProductForm(){el('productForm').reset();el('editingProduct').value='';if(selectedVendor)el('productVendor').value=selectedVendor;clearListingPhotos()}
function renderPhotoPreview(){el('photoPreview').innerHTML=listingPhotos.map((p,i)=>`<div class="photo-tile"><img src="${esc(p.preview||safeImage(p.url))}" alt="Product photo ${i+1}"><small>${i===0?'Cover photo':'Photo '+(i+1)}</small><button type="button" class="btn small" data-cover-photo="${i}" ${i===0?'disabled':''}>Use as cover</button><button type="button" class="btn small" data-remove-photo="${i}">Remove</button></div>`).join('')}
el('productPhotos').addEventListener('change',e=>{const files=[...e.target.files];if(listingPhotos.length+files.length>8){toast('Choose no more than eight photos');e.target.value='';return}if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5242880)){toast('Use JPG, PNG or WebP photos, no more than 5 MB each');e.target.value='';return}for(const file of files)listingPhotos.push({file,preview:URL.createObjectURL(file)});e.target.value='';renderPhotoPreview()});
el('addPhotoLink').addEventListener('click',()=>{const url=el('prodImage').value.trim();if(!safeImage(url)||!url.startsWith('https://')){toast('Enter a valid HTTPS photo link');return}if(listingPhotos.length>=8){toast('Maximum eight photos');return}listingPhotos.push({url});el('prodImage').value='';renderPhotoPreview()});el('newProduct').addEventListener('click',resetProductForm);
async function uploadListingPhotos(vendor){for(const p of listingPhotos){if(p.file&&p.uploadVendor!==vendor){const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[p.file.type];const path=`${vendor}/${crypto.randomUUID()}.${extension}`;const {error}=await db.storage.from('product-images').upload(path,p.file,{contentType:p.file.type,upsert:false});if(error)throw Error('Photo upload failed: '+error.message);p.url=db.storage.from('product-images').getPublicUrl(path).data.publicUrl;p.uploadVendor=vendor}}return listingPhotos.map(p=>p.url)}
async function editListing(id){const {data:p,error}=await db.from('products').select('*').eq('id',id).maybeSingle();if(error)throw error;if(!p)throw Error('Product not found');await loadOwnedBrands();if(!ownedBrands.some(v=>v.id===p.vendor_id))throw Error('Resume this store before editing its products');selectedVendor=p.vendor_id;resetProductForm();el('productVendor').value=p.vendor_id;el('sellerBrand').value=p.vendor_id;el('editingProduct').value=p.id;for(const [id,key] of Object.entries({prodName:'name',prodSku:'sku',prodDescription:'description',prodCategory:'category',prodPrice:'price_pkr',prodStock:'stock_quantity'}))el(id).value=p[key]??'';listingPhotos=(p.image_urls?.length?p.image_urls:p.image_url?[p.image_url]:[]).map(url=>({url}));renderPhotoPreview();await loadSellerProducts(p.vendor_id);go('sell');el('sellerProducts').scrollIntoView({behavior:'smooth'});}
el('reviewSearch').addEventListener('input',renderAdminProducts);el('reviewFilter').addEventListener('change',renderAdminProducts);
el('companyBrandForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const {error}=await db.rpc('create_company_brand',{p_name:el('brandName').value.trim(),p_logo:el('brandLogo').value.trim()||null,p_description:el('brandDescription').value.trim()});if(error)throw error;e.target.reset();toast('Company brand created');await loadAdmin();await loadOwnedBrands()})});
document.addEventListener('submit',e=>{if(e.target.matches('.vendor-offer')){e.preventDefault();submit(e.target,async()=>{const {error}=await db.rpc('offer_vendor_commission',{p_application_id:e.target.dataset.id,p_rate:Number(e.target.elements.rate.value)/100,p_note:e.target.elements.note.value.trim()});if(error)throw error;toast('Commission offer sent to vendor’s application');await loadAdmin()})}if(e.target.matches('.commission-payment')){e.preventDefault();submit(e.target,async()=>{await confirmSensitive('Record actual commission bank payment');const {error}=await db.rpc('record_commission_payment',{p_allocation_id:e.target.dataset.id,p_reference:e.target.elements.reference.value.trim()});if(error)throw error;toast('Payment recorded');await loadCommissionReport()})}});
document.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-photo]');if(remove){const [p]=listingPhotos.splice(Number(remove.dataset.removePhoto),1);if(p.preview?.startsWith('blob:'))URL.revokeObjectURL(p.preview);renderPhotoPreview()}const cover=e.target.closest('[data-cover-photo]');if(cover){listingPhotos.unshift(...listingPhotos.splice(Number(cover.dataset.coverPhoto),1));renderPhotoPreview()}const edit=e.target.closest('.edit-listing');if(edit)editListing(edit.dataset.id).catch(err=>toast(err.message));const manage=e.target.closest('.manage-brand');if(manage){selectedVendor=manage.dataset.id;loadOwnedBrands().then(()=>{go('sell');el('sellerProducts').scrollIntoView({behavior:'smooth'})}).catch(err=>toast(err.message))}
 const b=e.target.closest('.review-vendor,.review-product,.confirm-order,.archive-listing,.vendor-status,.accept-terms');if(!b)return;submit({querySelector:()=>b},async()=>{let result;if(b.matches('.review-vendor'))result=await db.rpc('admin_review_vendor_application',{p_application_id:b.dataset.id,p_approve:b.dataset.approve==='true',p_commission_rate:approvalValue('.approval-commission',b.dataset.id,b.dataset.approve==='true',100)});if(b.matches('.review-product'))result=await db.rpc('admin_review_product',{p_product_id:b.dataset.id,p_approve:b.dataset.approve==='true',p_ppv:approvalValue('.approval-ppv',b.dataset.id,b.dataset.approve==='true',1)});if(b.matches('.confirm-order'))result=await db.rpc('admin_confirm_order_payment',{p_order_id:b.dataset.id});if(b.matches('.archive-listing'))result=await db.rpc('archive_product',{p_product_id:b.dataset.id});if(b.matches('.vendor-status'))result=await db.rpc('admin_vendor_status',{p_vendor_id:b.dataset.id,p_status:b.dataset.status});if(b.matches('.accept-terms'))result=await db.rpc('accept_vendor_commission',{p_application_id:b.dataset.id});if(result?.error)throw result.error;toast('Saved');if(isAdmin)await loadAdmin();await loadSellerAgreement();await loadCatalog()})});
renderSplitInputs();

async function loadMemberCommissions(){const target=el('memberCommissionHistory');if(!target||!session)return;const uid=session.user.id;const {data,error}=await db.from('commission_allocations').select('*').eq('beneficiary_id',session.user.id).order('created_at',{ascending:false}).limit(100);if(error)throw error;if(session?.user.id!==uid)return;target.innerHTML=data?.length?data.filter(r=>!['buyer_discount','company'].includes(r.share_kind)).map(r=>`<div class="list-row"><strong>${esc(splitLabels[r.share_kind])} · ${money(r.amount_pkr)}</strong><span>${esc(r.status)}</span><small>${new Date(r.created_at).toLocaleString()}</small></div>`).join('')||'<p>No product commissions yet.</p>':'<p>No product commissions yet.</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('.gallery-photo');if(b){const img=el('productDetail').querySelector('.detail-image img');if(img&&safeImage(b.dataset.url))img.src=b.dataset.url}});

const memberManager=document.createElement('form');memberManager.id='memberManager';memberManager.className='form hidden';memberManager.innerHTML='<h3>Edit member account</h3><label>Full name<input name="full_name" required></label><label>Phone<input name="phone" minlength="5" required></label><label>Status<select name="status"><option value="active">Active</option><option value="suspended">Suspended</option></select></label><label>Reason for change<textarea name="reason" minlength="10" required></textarea></label><button class="btn primary">Verify & save member</button>';el('workspaceMembers').after(memberManager);
document.addEventListener('click',e=>{const b=e.target.closest('.edit-member');if(!b)return;const m=operationsMembers.find(m=>m.user_id===b.dataset.id);if(!m)return;memberManager.dataset.id=m.user_id;memberManager.elements.full_name.value=m.full_name;memberManager.elements.phone.value=m.phone||'';memberManager.elements.status.value=m.status;memberManager.elements.reason.value='';memberManager.classList.remove('hidden');memberManager.scrollIntoView({behavior:'smooth'})});
memberManager.addEventListener('submit',e=>{e.preventDefault();submit(memberManager,async()=>{await confirmSensitive('Update member account '+operationsMembers.find(m=>m.user_id===memberManager.dataset.id)?.member_code);const {error}=await db.rpc('manage_member_account',{p_member_id:memberManager.dataset.id,p_name:memberManager.elements.full_name.value.trim(),p_phone:memberManager.elements.phone.value.trim(),p_status:memberManager.elements.status.value,p_reason:memberManager.elements.reason.value.trim()});if(error)throw error;memberManager.reset();memberManager.classList.add('hidden');await loadOperationsMembers();toast('Member account saved')})});
document.addEventListener('submit',e=>{if(!e.target.matches('.resolve-commission'))return;e.preventDefault();submit(e.target,async()=>{await confirmSensitive('Assign verified missing commission recipient '+e.target.elements.code.value);const {error}=await db.rpc('resolve_commission_recipient',{p_allocation_id:e.target.dataset.id,p_member_code:e.target.elements.code.value.trim(),p_reason:e.target.elements.reason.value.trim()});if(error)throw error;toast('Held share released to verified recipient');await loadCommissionReport()})});

document.addEventListener('click',e=>{const b=e.target.closest('.share-product');if(b&&profile){const url=new URL(location.origin+location.pathname);url.searchParams.set('affiliate',profile.member_code);url.hash='product/'+b.dataset.id;navigator.clipboard.writeText(url.href).then(()=>toast('Selling link copied')).catch(()=>toast('Copy failed. Use your member code at checkout.'))}});

function updateSellerReferral(){const known=!!session&&!['suspended','closed'].includes(profile?.status)&&(profile?.status==='active'||hasApprovedPackage);el('sellerReferralField').classList.toggle('hidden',known);el('sellerExistingAccount').classList.toggle('hidden',!known);el('sellerIntroducer').required=!known;el('sellerIntroducer').disabled=known;if(known)el('sellerIntroducer').value='';}
function retailPriceLabel(p){const list=Number(p.compare_at_price_pkr),sale=Number(p.price_pkr);if(!Number.isFinite(list)||list<=sale||sale<=0)return '';const saved=Math.round((list-sale)*100)/100;return `<del class="original-price">${money(list)}</del> <small class="sale-saving">${Math.floor((list-sale)*100/list)}% off · Save ${money(saved)}</small>`}
updateSellerReferral();

async function loadRewardHolds(){let target=el('rewardHolds');if(!target){target=document.createElement('section');target.id='rewardHolds';target.className='card';el('memberCommissionHistory').before(target)}if(!session){target.replaceChildren();return}const uid=session.user.id;const {data,error}=await db.rpc('my_reward_holds');if(error)throw error;if(session?.user.id!==uid)return;const h=data||{};target.innerHTML=`<h3>Affiliate & first-level earnings</h3><p>Free members can share selling links and refer members. Inactive accounts earn first-level incentives only, held until a package activates. No self-purchase commission.</p><div class="list-row"><strong>Held direct income</strong><span>${Number(h.direct_mio||0).toFixed(4)} MIO</span></div><div class="list-row"><strong>Held affiliate commission</strong><span>${money(h.affiliate_pkr||0)}</span></div><div class="list-row"><strong>Held PPV / BV</strong><span>${Number(h.held_ppv||0).toFixed(4)} / ${Number(h.held_bv||0).toFixed(4)}</span></div><div class="list-row"><strong>Released earned PPV / BV</strong><span>${Number(h.released_ppv||0).toFixed(4)} / ${Number(h.released_bv||0).toFixed(4)}</span></div><p>${h.withdrawal_unlocked?'Package active: released earnings are available under payout rules.':'Withdrawal locked: activate a package with payment or your own shopping PPV. Held reward points do not activate your account.'}</p><p>Affiliate rate is set separately for each vendor by the company. PPV/BV are reward-point records, not an extra cash payout.</p>`;}
